SELECT i.id AS id, i.code AS code, i.name AS name, COALESCE(i.intro, '') AS intro, i.kind AS kind, i.visibility AS visibility, i.status AS status, i.owner AS owner, CASE WHEN i.owner = :learner OR EXISTS (SELECT 1 FROM subject_teacher t WHERE t.subject_id = i.id AND t.teacher = :learner AND t.role = 'owner') THEN 'owner' WHEN EXISTS (SELECT 1 FROM subject_teacher t WHERE t.subject_id = i.id AND t.teacher = :learner) THEN 'editor' ELSE 'public' END AS my_role, (SELECT COUNT(*) FROM subject_student s WHERE s.subject_id = i.id AND s.status = 'active') AS student_n, (CASE WHEN i.owner <> '' THEN 1 ELSE 0 END) + (SELECT COUNT(*) FROM subject_teacher t2 WHERE t2.subject_id = i.id AND t2.teacher <> i.owner) AS teacher_n FROM subject_info i WHERE i.owner = :learner OR i.id IN (SELECT subject_id FROM subject_teacher WHERE teacher = :learner) OR (i.visibility = 'public' AND i.status <> 'draft') ORDER BY i.id
